  stage: Exclude<AdvanceableRenderStage, RenderStage.Dynamic>
) {
  return RENDER_STAGE_ADVANCE_ORDER[
    RENDER_STAGE_ADVANCE_ORDER.indexOf(stage) + 1
  ]
